70	Value Value::MinimumValue(const LogicalType &type) {
71		switch (type.id()) {
72		case LogicalTypeId::BOOLEAN:
73			return Value::BOOLEAN(false);
74		case LogicalTypeId::TINYINT:
75			return Value::TINYINT(NumericLimits<int8_t>::Minimum());
76		case LogicalTypeId::SMALLINT:
77			return Value::SMALLINT(NumericLimits<int16_t>::Minimum());
78		case LogicalTypeId::INTEGER:
79		case LogicalTypeId::SQLNULL:
80			return Value::INTEGER(NumericLimits<int32_t>::Minimum());
81		case LogicalTypeId::BIGINT:
82			return Value::BIGINT(NumericLimits<int64_t>::Minimum());
83		case LogicalTypeId::HUGEINT:
84			return Value::HUGEINT(NumericLimits<hugeint_t>::Minimum());
85		case LogicalTypeId::UUID:
86			return Value::UUID(NumericLimits<hugeint_t>::Minimum());
87		case LogicalTypeId::UTINYINT:
88			return Value::UTINYINT(NumericLimits<uint8_t>::Minimum());
89		case LogicalTypeId::USMALLINT:
90			return Value::USMALLINT(NumericLimits<uint16_t>::Minimum());
91		case LogicalTypeId::UINTEGER:
92			return Value::UINTEGER(NumericLimits<uint32_t>::Minimum());
93		case LogicalTypeId::UBIGINT:
94			return Value::UBIGINT(NumericLimits<uint64_t>::Minimum());
95		case LogicalTypeId::DATE:
96			return Value::DATE(date_t(NumericLimits<int32_t>::Minimum()));
97		case LogicalTypeId::TIME:
98			return Value::TIME(dtime_t(0));
99		case LogicalTypeId::TIMESTAMP:
100			return Value::TIMESTAMP(timestamp_t(NumericLimits<int64_t>::Minimum()));
101		case LogicalTypeId::TIMESTAMP_SEC:
102			return Value::TimestampSec(timestamp_t(NumericLimits<int64_t>::Minimum()));
103		case LogicalTypeId::TIMESTAMP_MS:
104			return Value::TimestampMs(timestamp_t(NumericLimits<int64_t>::Minimum()));
105		case LogicalTypeId::TIMESTAMP_NS:
106			return Value::TimestampNs(timestamp_t(NumericLimits<int64_t>::Minimum()));
107		case LogicalTypeId::DATE_TZ:
108			return Value::DATETZ(date_t(NumericLimits<int32_t>::Minimum()));
109		case LogicalTypeId::TIME_TZ:
110			return Value::TIMETZ(dtime_t(0));
111		case LogicalTypeId::TIMESTAMP_TZ:
112			return Value::TIMESTAMPTZ(timestamp_t(NumericLimits<int64_t>::Minimum()));
113		case LogicalTypeId::FLOAT:
114			return Value::FLOAT(NumericLimits<float>::Minimum());
115		case LogicalTypeId::DOUBLE:
116			return Value::DOUBLE(NumericLimits<double>::Minimum());
117		case LogicalTypeId::DECIMAL: {
118			Value result;
119			switch (type.InternalType()) {
120			case PhysicalType::INT16:
121				result = Value::MinimumValue(LogicalType::SMALLINT);
122				break;
123			case PhysicalType::INT32:
124				result = Value::MinimumValue(LogicalType::INTEGER);
125				break;
126			case PhysicalType::INT64:
127				result = Value::MinimumValue(LogicalType::BIGINT);
128				break;
129			case PhysicalType::INT128:
130				result = Value::MinimumValue(LogicalType::HUGEINT);
131				break;
